export type MarkdownHeading = {
  /** Heading level, from 1 (top-level) to 6. */
  depth: number
  /** Plain-text heading content with all inline formatting removed. */
  value: string
}

/** Matches an ATX heading line, e.g. `## Example Heading ##`. */
const ATX_HEADING_REGEX = /^ {0,3}(#{1,6})(?:[ \t]+(.*?))?[ \t]*$/
/** Matches the closing hash sequence of an ATX heading (must be preceded by whitespace). */
const ATX_CLOSING_REGEX = /[ \t]+#+[ \t]*$/
/** Matches a setext underline made of `=` characters (depth 1). */
const SETEXT_H1_REGEX = /^ {0,3}=+[ \t]*$/
/** Matches a setext underline made of `-` characters (depth 2). */
const SETEXT_H2_REGEX = /^ {0,3}-+[ \t]*$/
/** Matches the opening (or closing) line of a fenced code block. */
const FENCE_REGEX = /^ {0,3}(`{3,}|~{3,})/
/** Matches a line that is indented enough to be an indented code block. */
const INDENTED_CODE_REGEX = /^(?: {4,}|\t)/

/**
 * Removes inline Markdown and HTML formatting from a heading, keeping the readable text.
 *
 * Handles inline code, images (keeps alt text), links (keeps link text), bold, strikethrough,
 * italic and HTML tags. The order matters: images are unwrapped before links, and bold before
 * italic, so the shorter markers do not consume the longer ones.
 */
const stripInlineFormatting = (input: string): string =>
  input
    // Inline code: `code` -> code
    .replace(/`([^`]+)`/g, '$1')
    // Images: ![alt](url) -> alt
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Links: [text](url) -> text
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Bold: **text** or __text__ -> text
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    // Strikethrough: ~~text~~ -> text
    .replace(/~~([^~]+)~~/g, '$1')
    // Italic: *text* or _text_ -> text
    .replace(/\*([^*]+)\*/g, '$1')
    .replace(/_([^_]+)_/g, '$1')
    // HTML tags: <b>text</b> -> text
    .replace(/<[^>]+>/g, '')
    .trim()

/** Returns true when a line is a valid text line to serve as a setext heading. */
const isSetextTextLine = (line: string | undefined): line is string => {
  if (line === undefined || line.trim() === '') {
    return false
  }

  // Must not be indented as a code block, an ATX heading, or another underline.
  return (
    !INDENTED_CODE_REGEX.test(line) &&
    !ATX_HEADING_REGEX.test(line) &&
    !SETEXT_H1_REGEX.test(line) &&
    !SETEXT_H2_REGEX.test(line)
  )
}

/**
 * Parses a Markdown string and returns its headings as an array of `{ depth, value }` objects.
 *
 * This is a dependency-free parser tailored for building navigation from headings. It recognizes:
 * - ATX headings (`# Heading` through `###### Heading`), including closing hashes (`## Heading ##`)
 * - Setext headings (text underlined with `=` for depth 1 or `-` for depth 2)
 *
 * Content inside fenced code blocks (``` or ~~~) and indented code blocks (4-space indent) is
 * ignored, and all inline formatting is stripped from the returned `value`.
 *
 * @param markdown - The Markdown string to parse
 * @returns Array of heading objects, or an empty array when there are no headings
 *
 * @example
 * getMarkdownHeadings('# Getting Started\n\nInstallation\n------------')
