 * Removes inline Markdown and HTML formatting from a heading, keeping the readable text.
 *
 * Handles inline code, images (keeps alt text), links (keeps link text), bold, strikethrough,
 * italic and HTML tags. The order matters: images are unwrapped before links, and bold before
 * italic, so the shorter markers do not consume the longer ones.
 */
const stripInlineFormatting = (input: string): string =>
  input
    // Inline code: `code` -> code
    .replace(/`([^`]+)`/g, '$1')
    // Images: ![alt](url) -> alt
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Links: [text](url) -> text
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    // Bold: **text** or __text__ -> text
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    // Strikethrough: ~~text~~ -> text
    .replace(/~~([^~]+)~~/g, '$1')
    // Italic: *text* or _text_ -> text
    .replace(/\*([^*]+)\*/g, '$1')
    .replace(/_([^_]+)_/g, '$1')
    // HTML tags: <b>text</b> -> text
    .replace(/<[^>]+>/g, '')
    .trim()

